import { c } from 'ttag';

import { CreateTokenData, createToken, getTokenStatus } from '@proton/shared/lib/api/payments';
import { PAYMENT_TOKEN_STATUS } from '@proton/shared/lib/constants';
import { wait } from '@proton/shared/lib/helpers/promise';
import { getHostname } from '@proton/shared/lib/helpers/url';
import { Api } from '@proton/shared/lib/interfaces';

import PaymentVerificationModal from './PaymentVerificationModal';
import {
    AmountAndCurrency,
    CardPayment,
    ExistingPayment,
    PaymentTokenResult,
    TokenPaymentMethod,
    WrappedCardPayment,
    isExistingPayment,
    isTokenPaymentMethod,
} from './interface';
import { toTokenPaymentMethod } from './paymentTokenToParams';

const { STATUS_PENDING, STATUS_CHARGEABLE, STATUS_FAILED, STATUS_CONSUMED, STATUS_NOT_SUPPORTED } =
    PAYMENT_TOKEN_STATUS;

const DELAY_PULLING = 5000;
const DELAY_LISTENING = 1000;

/**
 * Recursive function to check token status
 */
const pull = async ({
    timer = 0,
    Token,
    api,
    signal,
}: {
    timer?: number;
    Token: string;
    api: Api;
    signal: AbortSignal;
}): Promise<any> => {
    if (signal.aborted) {
        throw new Error(c('Error').t`Process aborted`);
    }

    if (timer > DELAY_PULLING * 30) {
        throw new Error(c('Error').t`Payment process canceled`);
    }

    const { Status } = await api({ ...getTokenStatus(Token), signal });

    if (Status === STATUS_FAILED) {
        throw new Error(c('Error').t`Payment process failed`);
    }

    if (Status === STATUS_CONSUMED) {
        throw new Error(c('Error').t`Payment process consumed`);
    }

    if (Status === STATUS_NOT_SUPPORTED) {
        throw new Error(c('Error').t`Payment process not supported`);
    }

    if (Status === STATUS_CHARGEABLE) {
        return;
    }

    if (Status === STATUS_PENDING) {
        await wait(DELAY_PULLING);
        return pull({ Token, api, timer: timer + DELAY_PULLING, signal });
    }

    throw new Error(c('Error').t`Unknown payment token status`);
};

/**
 * Initialize new tab and listen it
 */
export const process = (
    {
        Token,
        api,
        ApprovalURL,
        ReturnHost,
        signal,
    }: Pick<PaymentTokenResult, 'ApprovalURL' | 'ReturnHost' | 'Token'> & {
        api: Api;
        signal: AbortSignal;
    },
    delayListening = DELAY_LISTENING
) => {
    const tab = window.open(ApprovalURL);

    return new Promise<void>((resolve, reject) => {
        let listen = false;

        const reset = () => {
            listen = false;
            // eslint-disable-next-line @typescript-eslint/no-use-before-define
            window.removeEventListener('message', onMessage, false);
            // eslint-disable-next-line @typescript-eslint/no-use-before-define
            signal.removeEventListener('abort', abort);
        };

        const listenTab = async (): Promise<any> => {
            if (!listen) {
                return;
            }

            if (tab && tab.closed) {
                try {
                    reset();
                    const { Status } = await api({ ...getTokenStatus(Token), signal });
                    if (Status === STATUS_CHARGEABLE) {
                        return resolve();
                    }
                    throw new Error(c('Error').t`Tab closed`);
                } catch (error: any) {
                    return reject({ ...error, tryAgain: true });
                }
            }

            await wait(delayListening);
            return listenTab();
        };

        const onMessage = (event: MessageEvent) => {
            if (getHostname(event.origin) !== ReturnHost) {
                return;
            }

            reset();
            tab?.close();

            const { cancel } = event.data;

            if (cancel === '1') {
                return reject();
            }

            pull({ Token, api, signal }).then(resolve).catch(reject);
        };

        const abort = () => {
            reset();
            tab?.close();
            reject(new Error(c('Error').t`Process aborted`));
        };

        signal.addEventListener('abort', abort);
        window.addEventListener('message', onMessage, false);
        listen = true;
        listenTab();
    });
};

/**
 * Prepares the parameters and makes the API call to create the payment token.
 *
 * @param params
 * @param api
 * @param amountAndCurrency
 */
const fetchPaymentToken = async (
    {
        params,
        api,
    }: {
        params: WrappedCardPayment | ExistingPayment;
        api: Api;
    },
    amountAndCurrency?: AmountAndCurrency
): Promise<PaymentTokenResult> => {
    const data: CreateTokenData = { ...amountAndCurrency, ...params };

    return api<PaymentTokenResult>({
        ...createToken(data),
        notificationExpiration: 10000,
    });
};

/**
 * Creates a {@link TokenPaymentMethod} from the credit card details or from the existing (saved) payment method.
 * This function doesn't handle cash or Bitcoin payment methods because they don't require payment token.
 * This function doesn't handle PayPal methods because it's handled by {@link usePayPal} hook.
 *
 * @param params
 * @param api
 * @param createModal
 * @param mode
 * @param amountAndCurrency – optional. We can create a payment token even without amount and currency. In this case it
 * can't be used for payment purposes. But it still can be used to create a new payment method, e.g. save credit card.
 */
export const createPaymentToken = async (
    {
        params,
        api,
        createModal,
        mode,
    }: {
        createModal: (modal: JSX.Element) => void;
        mode?: 'add-card';
        api: Api;
        params: WrappedCardPayment | TokenPaymentMethod | ExistingPayment;
    },
    amountAndCurrency?: AmountAndCurrency
): Promise<TokenPaymentMethod> => {
    if (isTokenPaymentMethod(params)) {
        return params;
    }

    const { Token, Status, ApprovalURL, ReturnHost } = await fetchPaymentToken({ params, api }, amountAndCurrency);

    if (Status === STATUS_CHARGEABLE) {
        // If the payment token is already chargeable then we're all set. Just prepare the format and return it.
        return toTokenPaymentMethod(Token);
    }

    let Payment: CardPayment;
    if (!isExistingPayment(params)) {
        Payment = params.Payment;
    }

    /**
     * However there are other cases. The most common one (within the happy path) is {@link STATUS_PENDING}.
     * One typical reason is a 3DS verification requirement. In this case we show user a modal informing them about
     * 3DS verification in a new tab. While user is on the bank page, we call {@link process}. Essentially, it polls
     * the payment token status (e.g. every 5 seconds). Once {@link process} resolves then the entire return promise
     * resolves to a {@link TokenPaymentMethod} – newly created payment token.
     */
    return new Promise<TokenPaymentMethod>((resolve, reject) => {
        createModal(
            <PaymentVerificationModal
                mode={mode}
                payment={Payment}
                token={Token}
                onSubmit={resolve}
                onClose={reject}
                onProcess={() => {
                    const abort = new AbortController();
                    return {
                        promise: process({
                            Token,
                            api,
                            ReturnHost,
                            ApprovalURL,
                            signal: abort.signal,
                        }),
                        abort,
                    };
                }}
            />
        );
    });
};
import { useEffect, useRef, useState } from 'react';

import { c } from 'ttag';

import { Button } from '@proton/atoms';
import { ADD_CARD_MODE, PAYMENT_METHOD_TYPES } from '@proton/shared/lib/constants';
import { doNotWindowOpen } from '@proton/shared/lib/helpers/browser';
import errorSvg from '@proton/styles/assets/img/errors/error-generic.svg';

import { DoNotWindowOpenAlertError, FormModal, Loader, PrimaryButton } from '../../components';
import { useNotifications } from '../../hooks';
import PaymentVerificationImage from './PaymentVerificationImage';
import { CardPayment, TokenPaymentMethod } from './interface';
import { toTokenPaymentMethod } from './paymentTokenToParams';

const STEPS = {
    DO_NOT_WINDOW_OPEN: 'do_not_window_open',
    REDIRECT: 'redirect',
    REDIRECTING: 'redirecting',
    REDIRECTED: 'redirected',
    FAIL: 'fail',
};

const DEFAULT_PROCESSING_DELAY = 5000;

export interface PromiseWithController {
    promise: Promise<void>;
    abort: AbortController;
}

export interface Props {
    onSubmit: (paymentMethod: TokenPaymentMethod) => void;
    onClose: () => void;
    token: string;
    payment?: CardPayment | {};
    mode?: 'add-card';
    type?: PAYMENT_METHOD_TYPES.PAYPAL | PAYMENT_METHOD_TYPES.PAYPAL_CREDIT | PAYMENT_METHOD_TYPES.CARD;
    onProcess: () => PromiseWithController;
    initialProcess?: PromiseWithController;
    processingDelay?: number;
}

const PaymentVerificationModal = ({
    token,
    onSubmit,
    payment = {},
    mode,
    type = PAYMENT_METHOD_TYPES.CARD,
    onProcess,
    initialProcess,
    processingDelay = DEFAULT_PROCESSING_DELAY,
    ...rest
}: Props) => {
    const isAddCard = mode === ADD_CARD_MODE;
    const isPayPal = [PAYMENT_METHOD_TYPES.PAYPAL, PAYMENT_METHOD_TYPES.PAYPAL_CREDIT].includes(type);

    let failTitle;
    if (isPayPal) {
        failTitle = c('Title').t`PayPal verification failed`;
    } else if (isAddCard) {
        failTitle = c('Title').t`Verification failed`;
    } else {
        failTitle = c('Title').t`Payment failed`;
    }

    const TITLES = {
        [STEPS.DO_NOT_WINDOW_OPEN]: c('Title').t`Unsupported browser`,
        [STEPS.REDIRECT]: isAddCard ? c('Title').t`Card verification` : c('Title').t`Payment verification`,
        [STEPS.REDIRECTING]: c('Title').t`Processing...`,
        [STEPS.REDIRECTED]: isAddCard ? c('Title').t`Verifying your card...` : c('Title').t`Verifying your payment...`,
        [STEPS.FAIL]: failTitle,
    };

    const [step, setStep] = useState(() => (doNotWindowOpen() ? STEPS.DO_NOT_WINDOW_OPEN : STEPS.REDIRECT));
    const [error, setError] = useState<{ tryAgain?: boolean }>({});
    const { createNotification } = useNotifications();
    const abortRef = useRef<AbortController>();
    const timeoutRef = useRef<number>();

    const handleCancel = () => {
        abortRef.current?.abort();
        rest.onClose();
    };

    const handleSubmit = async ({ abort, promise }: PromiseWithController) => {
        try {
            setStep(STEPS.REDIRECTING);
            timeoutRef.current = window.setTimeout(() => {
                setStep(STEPS.REDIRECTED);
            }, processingDelay);
            abortRef.current = abort;
            await promise;
            onSubmit(toTokenPaymentMethod(token));
            rest.onClose();
        } catch (error: any) {
            window.clearTimeout(timeoutRef.current);
            setStep(STEPS.FAIL);
            setError(error);
            // if not coming from API error
            if (error.message && !error.config) {
                createNotification({ text: error.message, type: 'error' });
            }
        }
    };

    useEffect(() => {
        if (initialProcess) {
            handleSubmit(initialProcess);
        }
    }, []);

    useEffect(() => {
        return () => window.clearTimeout(timeoutRef.current);
    }, []);

    return (
        <FormModal
            title={TITLES[step]}
            onSubmit={() => handleSubmit(onProcess())}
            small
            noTitleEllipsis
            hasClose={false}
            footer={
                step === STEPS.REDIRECT ? (
                    <>
                        <Button type="reset">{c('Action').t`Cancel`}</Button>
                        <PrimaryButton type="submit">{c('Action').t`Verify`}</PrimaryButton>
                    </>
                ) : null
            }
            {...rest}
        >
            {{
                [STEPS.REDIRECT]: () => (
                    <>
                        <p className="text-center">
                            {isAddCard
                                ? c('Info').t`We need to authenticate your payment method with your bank.`
                                : c('Info').t`We need to authenticate your payment with your bank.`}
                        </p>
                        <p className="text-center">
                            <PaymentVerificationImage payment={payment} type={type} />
                        </p>
                        <div className="mb-4" data-testid="redirect-message">
                            {isAddCard
                                ? c('Info')
                                      .t`Verification will open a new tab, please disable any popup blockers. You will not be charged. Any amount used to verify the card will be refunded immediately.`
                                : c('Info')
                                      .t`The verification process will open a new browser tab. Please disable any active pop-up blockers.`}
                        </div>
                    </>
                ),
                [STEPS.REDIRECTING]: () => (
                    <>
                        <p className="text-center">
                            {isPayPal
                                ? c('Info').t`You will soon be redirected to PayPal to verify your payment.`
                                : c('Info').t`You may be redirected to your bank’s website.`}
                        </p>
                        <Loader />
                        <div className="mb-4" data-testid="redirecting-message">{c('Info')
                            .t`Don’t see anything? Remember to turn off pop-up blockers.`}</div>
                    </>
                ),
                [STEPS.REDIRECTED]: () => (
                    <>
                        <p className="text-center">
                            {isAddCard && !isPayPal
                                ? c('Info').t`Please authenticate your card in the verification tab.`
                                : c('Info').t`Please authenticate your payment in the verification tab.`}
                        </p>
                        <Loader />
                        <p className="text-center">
                            <Button onClick={handleCancel}>{c('Action').t`Cancel`}</Button>
                        </p>
                        <div className="mb-4" data-testid="redirected-message">{c('Info')
                            .t`Verification may take a few minutes.`}</div>
                    </>
                ),
                [STEPS.DO_NOT_WINDOW_OPEN]: () => (
                    <>
                        <DoNotWindowOpenAlertError />
                        <Button onClick={handleCancel}>{c('Action').t`Close`}</Button>
                    </>
                ),
                [STEPS.FAIL]: () => (
                    <div className="text-center" data-testid="fail-message">
                        <p>{!isAddCard && c('Info').t`We couldn’t process your payment.`}</p>
                        <img src={errorSvg} alt={c('Title').t`Error`} />
                        <p>
                            {isPayPal
                                ? c('Info')
                                      .t`Please try again, use a different payment method, or contact PayPal for assistance.`
                                : c('Info').t`Please try again using a different payment method, or contact your bank.`}
                        </p>
                        {error?.tryAgain ? (
                            <p>
                                <Button type="submit">{c('Action').t`Try again`}</Button>
                            </p>
                        ) : null}
                        <p>
                            <PrimaryButton onClick={handleCancel}>
                                {isAddCard
                                    ? c('Action').t`Use a different card`
                                    : c('Action').t`Use a different payment method`}
                            </PrimaryButton>
                        </p>
                    </div>
                ),
            }[step]()}
        </FormModal>
    );
};

export default PaymentVerificationModal;

